package com.aivle.project.messaging.quarantine;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
@Repository public class QuarantineRepository {
	private final JdbcTemplate jdbc;public QuarantineRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
	public record Journal(UUID id,String bodyHash,String keyHash,String headerHash,UUID claimedEventId,UUID dltEventId) { }
	private String consumer(String topic){return com.aivle.project.messaging.CustomReportTopics.STATUS.equals(topic)?"custom-report-status-cache-v1":"custom-report-jobs-v1";}
	public boolean insert(UUID id,String topic,int partition,long offset,byte[] body,int size,String bodyHash,boolean truncated,byte[] key,String keyHash,byte[] header,String headerHash,UUID claimedEvent,UUID claimedRequest,String reason,UUID dlt){return jdbc.update("INSERT IGNORE INTO quarantined_messages(id,consumer_name,source_topic,source_partition,source_offset,body_prefix,body_size,body_sha256,body_truncated,key_prefix,key_sha256,id_header,header_sha256,claimed_event_id,claimed_request_id,reason_code,dlt_event_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id.toString(),consumer(topic),topic,partition,offset,body,size,bodyHash,truncated,key,keyHash,header,headerHash,claimedEvent==null?null:claimedEvent.toString(),claimedRequest==null?null:claimedRequest.toString(),reason,dlt.toString())==1;}
	public Journal lockSource(String topic,int partition,long offset){return jdbc.queryForObject("SELECT * FROM quarantined_messages WHERE consumer_name=? AND source_topic=? AND source_partition=? AND source_offset=? FOR UPDATE",(r,n)->new Journal(UUID.fromString(r.getString("id")),r.getString("body_sha256"),r.getString("key_sha256"),r.getString("header_sha256"),uuid(r.getString("claimed_event_id")),UUID.fromString(r.getString("dlt_event_id"))),consumer(topic),topic,partition,offset);}
	public boolean isRequestSource(UUID id){return jdbc.queryForObject("SELECT COUNT(*) FROM quarantined_messages WHERE id=? AND consumer_name='custom-report-jobs-v1' AND source_topic=?",Integer.class,id.toString(),com.aivle.project.messaging.CustomReportTopics.REQUEST)==1;}
	public Journal lock(UUID id){return jdbc.query("SELECT * FROM quarantined_messages WHERE id=? FOR UPDATE",(r,n)->new Journal(id,r.getString("body_sha256"),r.getString("key_sha256"),r.getString("header_sha256"),uuid(r.getString("claimed_event_id")),UUID.fromString(r.getString("dlt_event_id"))),id.toString()).stream().findFirst().orElseThrow(()->new com.aivle.project.company.reportrequest.model.ReportRequestException(com.aivle.project.company.reportrequest.model.ReportRequestException.Code.NOT_FOUND));}
	public record Replay(UUID id,UUID quarantine,long actor,UUID request,String reason,String outcome,UUID event) { }
	public Optional<Replay> findCommand(UUID id){return jdbc.query("SELECT * FROM quarantine_replay_commands WHERE id=?",(r,n)->new Replay(id,UUID.fromString(r.getString("quarantine_id")),r.getLong("actor_user_id"),UUID.fromString(r.getString("target_request_id")),r.getString("reason"),r.getString("outcome"),uuid(r.getString("event_id"))),id.toString()).stream().findFirst();}
	public void recordReplay(Replay r){jdbc.update("INSERT INTO quarantine_replay_commands(id,quarantine_id,actor_user_id,target_request_id,reason,outcome,event_id) VALUES(?,?,?,?,?,?,?)",r.id().toString(),r.quarantine().toString(),r.actor(),r.request().toString(),r.reason(),r.outcome(),r.event()==null?null:r.event().toString());if(r.event()!=null)jdbc.update("UPDATE quarantined_messages SET replay_event_id=? WHERE id=?",r.event().toString(),r.quarantine().toString());}
	private UUID uuid(String text){return text==null?null:UUID.fromString(text);}
}
